command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: SCHNURREN DER MUTTER (Ausführung)
// ==========================================

(async () => {
    let fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (fwMacro) { await fwMacro.execute(); }

    const DSK_FW = globalThis.DSK || DSK;
    if (typeof DSK_FW === "undefined") return ui.notifications.error("Luna sagt 🌙: Framework fehlt!");

    const gabenName = "Schnurren der Mutter";
    const ahne = "nurti"; 
    const finalEffektName = `${gabenName} (${ahne})`;
    const iconBild = DSK_FW.Symbol(ahne);

    const getOwners = (act) => Object.entries(act?.ownership || {}).filter(([id, lvl]) => lvl === 3 && id !== "default").map(([id]) => id);

    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character;
    if (!casterActor) casterActor = game.actors.find(a => a.getFlag("world", "letzteGabenQS") !== undefined);
    if (!casterActor) {
        for (let t of canvas.tokens.placeables) {
            if (t.actor && t.actor.getFlag("world", "letzteGabenQS") !== undefined) { casterActor = t.actor; break; }
        }
    }
    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");

    const qs = Number(casterActor.getFlag("world", "letzteGabenQS") || 1);
    const alteMessageId = casterActor.getFlag("world", "letzteGabenMessageId");

    let whisperIds = new Set(game.users.filter(u => u.isGM).map(u => u.id));
    getOwners(casterActor).forEach(id => whisperIds.add(id));

    const targets = Array.from(game.user.targets);
    if (targets.length === 0) {
        return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst jemanden per Target aus, den du beschnurren möchtest!");
    }

    if (targets.length > qs) {
        return ui.notifications.warn(`Luna sagt 🌙: Deine QS (${qs}) reicht nicht aus, um so viele Ziele gleichzeitig zu beschnurren! (Maximal ${qs} Ziele)`);
    }

    const maxIntervalle = qs;
    const dialogContent = `
        <div style="font-family: 'Signika', sans-serif;">
            ${DSK_FW.UI.Header(finalEffektName, iconBild)}
            <div class="dskbox2" style="margin-top: 10px; color: #000; text-align: left;">
                <p style="margin-bottom: 10px;"><b>Wie lange möchtest du das Ziel beschnurren?</b></p>
                <p style="font-size: 0.9em; margin-bottom: 10px; color: #555;">(Jedes 10-Minuten-Intervall heilt 1 LeP. Deine QS erlaubt maximal <b>${maxIntervalle}</b> Intervalle.)</p>
                <div style="display: flex; align-items: center; justify-content: flex-start; gap: 10px; margin-bottom: 5px;">
                    <label style="font-weight: bold;">10-Minuten-Intervalle:</label>
                    <input type="number" id="putzIntervalle" value="${maxIntervalle}" min="1" max="${maxIntervalle}" style="width: 60px; text-align: center; border: 1px solid #76301b; border-radius: 3px;">
                </div>
            </div>
        </div>
    `;

    new Dialog({
        title: `Schnurren (Max: ${maxIntervalle * 10} Min)`,
        content: dialogContent,
        buttons: {
            confirm: {
                icon: '<i class="fas fa-heart"></i>',
                label: "Schnurren & Heilen",
                callback: async (html) => {
                    const container = html instanceof jQuery ? html[0] : html;
                    let intervalleEingabe = Number(container.querySelector("#putzIntervalle").value) || 0;

                    if (intervalleEingabe <= 0) {
                        ui.notifications.warn("Luna sagt 🌙: Du musst schon mindestens 10 Minuten schnurren!");
                        return;
                    }
                    if (intervalleEingabe > maxIntervalle) intervalleEingabe = maxIntervalle;

                    const minutenGesamt = intervalleEingabe * 10;
                    const erfolge = [];
                    const fehler = [];

                    for (let t of targets) {
                        if (!t.actor) continue;

                        const zielSpezies = (t.actor.system?.details?.species?.value || t.actor.system?.details?.species || t.actor.system?.species?.value || "").toLowerCase();
                        const isGeist = DSK_FW.Effekt.CheckTarget(t.actor, "geist") || zielSpezies.includes("geist");
                        const isUntot = zielSpezies.includes("untot") || zielSpezies.includes("skelett") || zielSpezies.includes("zombie");
                        const isVampir = zielSpezies.includes("vampir");
                        const isDaemon = zielSpezies.includes("dämon") || zielSpezies.includes("daemon");
                        const isElementar = zielSpezies.includes("elementar");
                        const isGolem = zielSpezies.includes("golem") || zielSpezies.includes("homunkulus");

                        let istLebewesen = !(isGeist || isUntot || isVampir || isDaemon || isElementar || isGolem);

                        if (!istLebewesen) {
                            fehler.push({ name: t.name, grund: "Kein Lebewesen" });
                            continue;
                        }

                        const maxLeP = t.actor.system.stats.LeP.max;
                        const currentLeP = t.actor.system.stats.LeP.value;

                        if (currentLeP >= maxLeP) {
                            fehler.push({ name: t.name, grund: "Bereits volle LeP" });
                            continue;
                        }

                        let healAmount = intervalleEingabe; 
                        let neueLeP = currentLeP + healAmount;
                        if (neueLeP > maxLeP) {
                            healAmount = maxLeP - currentLeP;
                            neueLeP = maxLeP;
                        }

                        await t.actor.update({"system.stats.LeP.value": neueLeP});
                        erfolge.push({ name: t.name, amount: healAmount, total: neueLeP, max: maxLeP });
                    }

                    targets.forEach(t => {
                        if(t?.actor) Object.entries(t.actor.ownership || {}).filter(([id, lvl]) => lvl === 3).forEach(([id]) => whisperIds.add(id));
                    });

                    const erfolgHtml = erfolge.length > 0 
                        ? `<div style="margin-top: 10px; margin-bottom: 10px; text-align: left;">
                               <p style="margin-bottom: 5px;"><span style="color:#18940F; font-weight:bold;">Erfolgreich geheilt:</span></p>
                               <ul class="dsklist" style="margin-top:0; font-weight:normal; color: #000; text-align: left;">
                                   ${erfolge.map(e => `<li><b>${e.name}</b> <span style="color: #2e7d32;">(+${e.amount} LeP)</span> ➔ ${e.total}/${e.max}</li>`).join("")}
                               </ul>
                           </div>` : ``;

                    const fehlschlagHtml = fehler.length > 0
                        ? `<div style="margin-top: 10px; margin-bottom: 10px; text-align: left;">
                               <p style="margin-bottom: 5px;"><span style="color:#B30000; font-weight:bold;">Fehlschlag:</span></p>
                               <ul class="dsklist" style="margin-top:0; font-weight:normal; color: #000; text-align: left;">
                                   ${fehler.map(f => `<li>${f.name} (${f.grund})</li>`).join("")}
                               </ul>
                           </div>` : ``;

                    const resultHtml = `
                        <div style="font-family: 'Signika', sans-serif;">
                            ${DSK_FW.UI.Header(finalEffektName, iconBild)}
                            <div class="dskbox2" style="margin-top:10px;">
                                <p style="margin-bottom: 8px; text-align: left;"><b>${casterActor.name}</b> hält Körperkontakt und beginnt tief und beruhigend zu schnurren.</p>
                                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                                <p style="margin-top:0; margin-bottom:8px; text-align: left;">Das vibrierende Schnurren durchdringt den Körper des Ziels, schließt langsam die Wunden und kann im Notfall sogar vor dem Tod bewahren.</p>
                                ${erfolgHtml}
                                ${fehlschlagHtml}
                                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                                <p style="text-align:center; font-weight:bold; margin-bottom: 0;">
                                    Dauer des Schnurrens:<br>${minutenGesamt} Minuten
                                </p>
                            </div>
                        </div>
                    `;

                    await casterActor.unsetFlag("world", "letzteGabenQS");
                    await casterActor.unsetFlag("world", "letzteGabenMessageId");

                    let msg = alteMessageId ? game.messages.get(alteMessageId) : null;
                    if (msg) {
                        await msg.update({ content: resultHtml, whisper: Array.from(whisperIds) });
                    } else {
                        await ChatMessage.create({
                            speaker: { alias: "System" },
                            whisper: Array.from(whisperIds).filter(id => game.users.get(id)),
                            content: resultHtml
                        });
                    }
                }
            },
            cancel: {
                icon: '<i class="fas fa-times"></i>',
                label: "Abbrechen"
            }
        },
        default: "confirm",
        render: (html) => {
            const container = html instanceof jQuery ? html[0] : html;
            const btns = container.querySelectorAll('.dialog-button');
            btns.forEach(btn => {
                btn.style.background = 'linear-gradient(#76301b,#582617)';
                btn.style.color = '#f8f6f5';
                btn.style.border = '1px solid #000';
                btn.style.fontWeight = 'bold';
            });
        }
    }).render(true);
})();
